update public.content_variants set body = $json${"type":"fill_blank","answer":"demand and supply","question":"Crypto prices are determined by _____ and _____, so they can rise or fall very quickly.","difficulty":"beginner","explanation":"There is no central bank that sets crypto prices. The price is purely based on demand and supply in the market."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"permintaan dan penawaran","question":"Harga kripto ditentukan oleh _____ dan _____, sehingga bisa naik atau turun sangat cepat.","difficulty":"beginner","explanation":"Tidak ada bank sentral yang menetapkan harga kripto. Harganya murni dari permintaan dan penawaran di pasar."}$json$::jsonb where id = 'dbc0e95a-59c2-4a21-b62a-21929a2454d8';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"ETF Jakarta Islamic Index (XLIJ)","options":["ETF LQ45 (XISX)","ETF Jakarta Islamic Index (XLIJ)","ETF IDX30 (XIIS)","All of the above ETFs"],"question":"Which ETFs are Sharia compliant?","difficulty":"intermediate","explanation":"XLIJ ETF tracks the Jakarta Islamic Index which only contains shares of companies that comply with Islamic sharia principles."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"ETF Jakarta Islamic Index (XLIJ)","options":["ETF LQ45 (XISX)","ETF Jakarta Islamic Index (XLIJ)","ETF IDX30 (XIIS)","Semua ETF di atas"],"question":"ETF mana yang sesuai syariah?","difficulty":"intermediate","explanation":"ETF XLIJ melacak Jakarta Islamic Index yang hanya berisi saham-saham perusahaan yang sesuai dengan prinsip syariah Islam."}$json$::jsonb where id = 'e25264fb-5440-4a3c-9cce-c0990c689eba';
update public.content_variants set body = $json${"type":"fill_blank","answer":"FOMO","question":"It's best to stay away from crypto if you feel _____ and don't understand the asset.","difficulty":"beginner","explanation":"FOMO (fear of missing out) often leads to loss-making speculative decisions."}$json$::jsonb, body_id = $json${"type":"fill_blank","answer":"FOMO","question":"Sebaiknya menjauh dari kripto jika kamu merasa _____ dan belum memahami asetnya.","difficulty":"beginner","explanation":"FOMO (takut ketinggalan) sering menyebabkan keputusan spekulatif yang merugi."}$json$::jsonb where id = 'e631ec8b-29b2-4805-b086-0728d3e474a0';
update public.content_variants set body = $json${"text":"Doni bought a laptop for IDR 10 million using a credit card and chose to pay a minimum of IDR 500 thousand per month. 2% interest per month on the remaining balance. After a year, he had paid IDR 6 million but still had a debt of around IDR 8 million because interest continued to accumulate."}$json$::jsonb, body_id = $json${"text":"Doni membeli laptop Rp 10 juta pakai kartu kredit dan memilih bayar minimum Rp 500 ribu per bulan. Bunga 2% per bulan mengenai sisa tagihan. Setelah setahun, ia sudah membayar Rp 6 juta tetapi masih punya utang sekitar Rp 8 juta karena bunga terus menumpuk."}$json$::jsonb where id = 'e6d391d6-085c-484d-bc3d-1fdc22fe30e6';
update public.content_variants set body = $json${"type":"multiple_choice","answer":"Make sure the purchase is within the budget and read the cost terms","options":["Make sure the purchase is within the budget and read the cost terms","Checkout immediately because the promo is only a few hours","Lending an account to a friend","Ignoring due dates"],"question":"What should you do before using PayLater?","difficulty":"beginner","explanation":"PayLater is safe only if you have planned payments and understand penalties and interest."}$json$::jsonb, body_id = $json${"type":"multiple_choice","answer":"Memastikan pembelian sudah masuk anggaran dan membaca ketentuan biaya","options":["Memastikan pembelian sudah masuk anggaran dan membaca ketentuan biaya","Langsung checkout karena promo hanya beberapa jam","Meminjamkan akun ke teman","Mengabaikan tanggal jatuh tempo"],"question":"Apa yang sebaiknya dilakukan sebelum menggunakan PayLater?","difficulty":"beginner","explanation":"PayLater aman hanya jika kamu sudah merencanakan pembayaran dan memahami denda serta bunga."}$json$::jsonb where id = 'e71bce78-73e9-4413-b21a-7824bbe83e2c';

